      for (const [index, photo] of editingPhotos.entries()) { setUploadStates((current) => ({ ...current, [photoKey(photo)]: "uploading" })); const extension = photo.type === "image/jpeg" ? "jpg" : photo.type.split("/")[1], path = `${tripId}/${editing.id}/${paths.length + index + 1}-${crypto.randomUUID()}.${extension}`; const { error } = await supabase.storage.from("trip-journal").upload(path, photo, { contentType: photo.type }); if (error) { setUploadStates((current) => ({ ...current, [photoKey(photo)]: "error" })); throw error; } paths.push(path); uploaded.push(path); sizeDraft[path]=photo.size; setUploadStates((current) => ({ ...current, [photoKey(photo)]: "done" })); }
