      const videoCaptions=Object.fromEntries(Object.entries(videoCaptionDraft).filter(([path])=>videoPaths.includes(path))),videoSizes=Object.fromEntries(Object.entries(videoSizeDraft).filter(([path])=>videoPaths.includes(path)));
