  function captureMoment() {
    const today = new Date().toISOString().slice(0, 10);
    const day = today < start ? start : today > end ? end : today;
    setDate(day);
    setLocation([...stops].filter((stop) => stop.arrive && stop.arrive <= day).sort((a, b) => (b.arrive ?? "").localeCompare(a.arrive ?? ""))[0]?.name ?? stops[0]?.name ?? "");
    titleInput.current?.focus();
    titleInput.current?.scrollIntoView({ behavior: "smooth", block: "center" });
  }

